    keys = Object.keys(obj);
  }

  // Create an array of values for the given keys
  const values = keys.reduce((acc, curr) => {
    acc[curr] = obj[curr];
    return acc;
  }, {});

  // Sort the values array by the specified keys
  keys.forEach((key, i) => {
    values[key] = obj[key];
    delete obj[key];
    values[key] = sortValuesByKey(values[key], keys[i + 1]);
    obj[key] = values[key];
  });

  // Remove the temporary values object
  delete values;

  // Return the sorted object
  return obj;
}

// Helper function to recursively sort nested objects or arrays
function sortValuesByKey(val, nextKey) {
  // Base case: primitive value or no next key
  if (typeof val !== "object" || typeof nextKey === "undefined") {
    return val;
  }

  // Recursive case: sort nested objects/arrays by next key
  const sorted = {};
  Object.keys(val).sort().forEach(key => {
    sorted[key] = sortValuesByKey(val[key], nextKey);
  });
  return sorted;
}
```

This function takes an object `obj` and an optional array of keys `keys`. By default, it sorts the entire object by all keys, but you can provide a specific list of keys to sort by instead. The function creates a temporary `values` object with just the values for the selected keys, sorts them by their indices in the `keys` array, then merges the sorted values back into the original object, deleting the `values` object afterward. This ensures that nested

