response:
Here's the implementation of bubble sort in C++ for sorting the given array:

```cpp
#include <iostream>

const int MAX_SIZE = 100; // Maximum size of the array

void bubbleSort(int arr[], int n) {
    bool swapped = false; // Flag to check if any swap is made in a pass
    for (int i = 0; i < n - 1; i++) {
        swapped = false;
        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j+1]) {
                int temp = arr[j];
                arr[j] = arr[j+1];
                arr[j+1] = temp;
                swapped = true;
            }
        }
        // If no two adjacent elements were swapped, the list is sorted
        // We can break out of the loop
        if (!swapped) break;
    }
}

int main() {
    int arr[MAX_SIZE], n;
    std::cout << "Enter the number of elements: ";
    std::cin >> n;
    std::cout << "Enter " << n << " integers:\n";
    for (int i=0; i<n; i++) {
        std::cin >> arr[i];
    }
    bubbleSort(arr, n);
    std::cout << "Sorted Array:\n";
    for (int i=0; i<n; i++) {
        std::cout << arr[i] << " ";
    }
    return 0;
}
```

