const cors = require('cors');

module.exports = function (req, res, next) {
  const origin = req.headers.origin;

  if (!origin || !allowedOrigins.includes(origin)) {
    res.status(403).send('Forbidden');
    return;
  }

  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');

  next();
};

const allowedOrigins = ['https://your-nextjs-app.com', 'http://localhost:3000'];
```

In this example, `allowedOrigins` is an array of allowed origins where your Next.js app can make requests to the WordPress REST API. You can replace this array with your specific domain or localhost URLs.

