```javascript
const cors = require('cors');

module.exports = function (req, res, next) {
  // ...

  const middleware = cors({
    origin: (origin, callback) => {
      if (!origin || !allowedOrigins.includes(origin)) {
        return callback(null, false);
      }
      callback(null, true);
    },
  });

  middleware(req, res, next);
};
```

