    relevanceB += 91;
  }

  // Check for UDP packets
  if (inputData.protocol === "udp") {
    relevanceC += 91;
  }

  // Return the protocol with the highest relevance score
  return relevanceA > relevanceB && relevanceA > relevanceC ? "IPv6" : relevanceB > relevanceC ? "HTTP" : "UDP";
}

