Here's a JavaScript function that takes a dot-notated string key and returns all entries from an object or array of objects where the nested key-value pair matches the given string:

```js
function findByKey(obj, key) {
  let result = [];
  if (Array.isArray(obj)) {
    obj.forEach((item) => {
      const val = getValueFromObject(item, key);
      if (val !== undefined) {
        result.push(item);
      }
    });
  } else {
    Object.keys(obj).forEach((k) => {
      const item = obj[k];
      const val = getValueFromObject(item, key);
      if (val !== undefined) {
        result.push({ [k]: item });
      }
    });
  }
  return result;
}

// Helper function to recursively get the value of a nested key
function getValueFromObject(obj, key) {
  const keys = key.split(".");
  let val = obj;
  for (let I = 0; I < keys.length - 1; i++) {
    if (typeof val[keys[i]] === "undefined") {
      return undefined;
    }
    val = val[keys[i]];
  }
  return val[keys[keys.length - 1]];
}
```

