#!/bin/bash

awk -F, '
BEGIN {
  print "Intersectional Analysis Report"
  print "------------------------------"
}

{
  # Count total number of employees
  total++

  # Count number of women of color in leadership roles
  if ( $3 ~ /Leadership/ && $5 ~ /Black/ && $6 ~ /Female/ ) {
    woc_leaders++
  }

  # Count number of men with disabilities in entry-level positions
  if ( $3 ~ /Entry-Level/ && $7 ~ /Male/ && $8 ~ /Disability/ ) {
    m_disabilities++
  }

  # Count number of LGBTQ+ employees in sales
