    lgbtq_sales++
  }
}

END {
  print ""
  print "Total Employees:", total
  print "Women of Color in Leadership Roles:", woc_leaders
  print "Men with Disabilities in Entry-Level Positions:", m_disabilities
  print "LGBTQ+ Employees in Sales:", lgbtq_sales
