% Loop through generations
for gen = 1:gen_num
    % Calculate fitness values
    fit = fav_fit.*pop(:).*pop(:)' + unfav_fit*(1-pop(:)).*(1-pop(:)');
    % Normalize fitness values
    fit = fit ./ sum(fit);
    % Generate offspring using roulette wheel selection
    offspring = zeros(pop_size,1);
    while sum(offspring(:)) < pop_size
        parent1 = floor(pop_size*rand(1,1));
        parent2 = floor(pop_size*rand(1,1));
        if ~isnan(parent1) && ~isnan(parent2)
            child = fav_fit + (unfav_fit-fav_fit)*(parent1+parent2)/2;
            offspring(mod(sum(offspring(:))+1,pop_size)+1) = child;
            % Introduce mutation with probability mut_rate
