import { Injectable, NestMiddleware } from 'nestjs';
import { Observable } from 'rxjs';
import { map } from 'rxjs/operators';

@Injectable()
export class DevelopmentOnlyMiddleware implements NestMiddleware {
  constructor() {}

  use(req: any, res: any, next: () => Observable<any>, ...args: any[]): Observable<any> {
    if (process.env.NODE_ENV === 'development') {
      return next().pipe(map(() => null)); // Call next() and return null to indicate success
    } else {
      return new Observable(() => {}); // Return empty observable to indicate failure
    }
  }
}

// Usage example:
// Decorate your controller method with the developmentOnly decorator
// @UseGuards(AuthGuard)
// @DevelopmentOnly()
// getUsers(): any {
//   // Implementation here...
// }

function DevelopmentOnly(target: Object, propertyKey: string | symbol) {
  const originalMethod = Reflect.getOwnMetadata('originalMethod', target, propertyKey);
  Reflect.defineMetadata('originalMethod', (...args: any[]) => {
    const result = Reflect.getOwnMetadata('result', target, propertyKey);
    const isSuccessful = Reflect.getOwnMetadata('isSuccessful', target, propertyKey);

    if (isSuccessful || process.env.NODE_ENV !== 'development') {
      return result;
    } else {
      throw new Error('This endpoint is disabled in production mode.');
    }
  }, target, propertyKey);
  Reflect.defineMetadata('result', originalMethod, target, propertyKey);
  Reflect.defineMetadata('isSuccessful', false, target, propertyKey);
}

// Example usage:
// This allows you to avoid checking NODE_ENV manually in your controller methods
// @Get('/users')
// @DevelopmentOnly()
// getUsers(): User[] {
//   return userService.getUsers();
// }
```

